// Solo permitimos borrar una ruta perteneciente al token y servicio declarados.
const submissionToken=String(context.parameters['submission_token']||'').trim();
const serviceKey=String(context.parameters['service_key']||'').trim();
const categoria=String(context.parameters['categoria']||'').trim();
const path=String(context.parameters['path']||'').trim();
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const safe=/^[a-z0-9_]+$/;
const prefix=`pedidos/${submissionToken}/${serviceKey}/${categoria}/`;
const filePattern=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\.(jpg|png|webp|pdf|doc|docx|xls|xlsx|mp4|webm|mov|txt)$/i;
const fileName=path.slice(prefix.length);
const valid=uuid.test(submissionToken)&&safe.test(serviceKey)&&safe.test(categoria)&&path.startsWith(prefix)&&filePattern.test(fileName)&&!path.includes('..');
return {valid,path};

PREPARE_FILE.code:
// Validamos todos los archivos seleccionados con sus metadatos reales.
const submissionToken=String(context.parameters['submission_token']||'').trim();
const areaId=String(context.parameters['area_id']||'').trim();
const tipoServicioId=String(context.parameters['tipo_servicio_id']||'').trim();
const serviceKey=String(context.parameters['service_key']||'').trim();
const categoria=String(context.parameters['categoria']||'').trim();
const received=context.parameters['file'];
const files=Array.isArray(received)?received:(received?[received]:[]);
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const safe=/^[a-z0-9_]+$/;
if(!uuid.test(submissionToken)||!uuid.test(areaId)||!uuid.test(tipoServicioId)||!safe.test(serviceKey)||!safe.test(categoria)||files.length===0){
 return {valid:false,code:'VALIDATION_ERROR',message:'Los identificadores o archivos de la carga no son válidos.'};
}
const mimeByCategory={
 fotografia:['image/jpeg','image/png','image/webp'],logo:['image/jpeg','image/png','image/webp'],firma:['image/jpeg','image/png','image/webp'],
 video:['video/mp4','video/webm','video/quicktime'],
 documento:['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','text/plain'],
 referencia:['image/jpeg','image/png','image/webp','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','video/mp4','video/webm','video/quicktime','text/plain'],
 contenido_adicional:['image/jpeg','image/png','image/webp','application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','text/plain']
};
const extensionByMime={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','application/pdf':'pdf','application/msword':'doc','application/vnd.openxmlformats-officedocument.wordprocessingml.document':'docx','application/vnd.ms-excel':'xls','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':'xlsx','video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov','text/plain':'txt'};
const items=[];
for(const file of files){
 const originalName=String(file?.name||'').trim();
 const mimeType=String(file?.type||'').toLowerCase();
 const sizeBytes=Number(file?.size||0);
 if(!originalName||!mimeType||!Number.isFinite(sizeBytes)||sizeBytes<=0){
  return {valid:false,code:'INVALID_FILE_METADATA',message:'No fue posible verificar nombre, tipo MIME y tamaño real de todos los archivos.'};
 }
 if(!mimeByCategory[categoria]?.includes(mimeType)){
  return {valid:false,code:'FILE_TYPE_NOT_ALLOWED',message:'Uno de los tipos de archivo no está permitido para esta categoría.'};
 }
 const path=`pedidos/${submissionToken}/${serviceKey}/${categoria}/${crypto.randomUUID()}.${extensionByMime[mimeType]}`;
 items.push({file,path,nombre_original:originalName,mime_type:mimeType,size_bytes:sizeBytes,categoria});
}
return {valid:true,submissionToken,areaId,tipoServicioId,serviceKey,categoria,items};
